"use strict";(globalThis.webpackChunktemp_dir=globalThis.webpackChunktemp_dir||[]).push([[6551],{9854(i){i.exports=JSON.parse('{"tag":{"label":"robotics","permalink":"/notes/tags/robotics","allTagsPath":"/notes/tags","count":18,"items":[{"id":"convex-mpc/wasm","title":"Convex MPC in the Browser","description":"An interactive WebAssembly viewer for convex model-predictive control and quadruped locomotion.","permalink":"/notes/convex-mpc/wasm"},{"id":"modern-robotics/wasm","title":"Modern Robotics in the Browser","description":"A WebGL and WebAssembly playground for forward kinematics, inverse kinematics, planning, and dynamics.","permalink":"/notes/modern-robotics/wasm"},{"id":"modern-robotics/summary","title":"Modern Robotics Series Summary - From Geometry to Control and Planning","description":"A compact summary of the full Modern Robotics series, connecting rigid-body motion, screw theory, Jacobians, inverse kinematics, dynamics, and motion planning into one coherent picture.","permalink":"/notes/modern-robotics/summary"},{"id":"modern-robotics/part-1","title":"Modern Robotics, Part 1 \u2014 Rigid-Body Motion and the Product of Exponentials","description":"A mathematically grounded introduction to Modern Robotics, covering rigid-body motion, twists, screw axes, and the Product of Exponentials formulation behind robot kinematics.","permalink":"/notes/modern-robotics/part-1"},{"id":"modern-robotics/part-2a","title":"Modern Robotics, Part 2A \u2014 Screw Axes, Twists, and the Exponential Map","description":"A detailed mathematical walkthrough of screw axes, twists, and the exponential map in Modern Robotics, forming the basis for robot kinematics and Jacobian computation.","permalink":"/notes/modern-robotics/part-2a"},{"id":"modern-robotics/part-2b","title":"Modern Robotics, Part 2B \u2014 Frames, Lie Groups, and the Jacobian Bridge","description":"A continuation of the screw-theory introduction, focusing on spatial vs. body frames, Lie group/Lie algebra intuition, and the connection to Jacobian construction.","permalink":"/notes/modern-robotics/part-2b"},{"id":"modern-robotics/part-3","title":"Modern Robotics, Part 3 \u2014 Jacobians and End-Effector Velocity","description":"A detailed derivation of the Jacobian from screw axes and twists, showing how end-effector velocity is computed from joint rates and why singularities arise.","permalink":"/notes/modern-robotics/part-3"},{"id":"modern-robotics/part-4","title":"Modern Robotics, Part 4 \u2014 Manipulability and Velocity Control","description":"A deeper look at Jacobian-based velocity control, manipulability measures, and pseudoinverse methods for achieving task-space motion under constraints.","permalink":"/notes/modern-robotics/part-4"},{"id":"modern-robotics/part-5","title":"Modern Robotics, Part 5 \u2014 Inverse Kinematics and Numerical Solvers","description":"A detailed explanation of inverse kinematics using Jacobian-based methods, analytic solutions, and iterative numerical strategies for robot pose solving.","permalink":"/notes/modern-robotics/part-5"},{"id":"modern-robotics/part-6a","title":"Modern Robotics, Part 6A \u2014 Dynamics, Control, and Motion Generation","description":"A deep-dive connecting kinematics, twist-based motion generation, and dynamics to task-space control and robot motion generation.","permalink":"/notes/modern-robotics/part-6a"},{"id":"modern-robotics/part-6b","title":"Modern Robotics, Part 6B \u2014 Trajectories, Constraints, and Motion Planning","description":"A continuation of the kinematics-to-planning story, focused on trajectory generation, time scaling, constraints, and the geometry behind motion planning.","permalink":"/notes/modern-robotics/part-6b"},{"id":"optimal-parking/summary","title":"Optimal Parking Series Summary - From Sampling to Optimized Trajectory","description":"A compact map of the Optimal Parking planner, from the kinematic bicycle model and RRT* seed to sequential QP refinement and browser execution.","permalink":"/notes/optimal-parking/summary"},{"id":"optimal-parking/part-1","title":"Optimal Parking, Part 1 - Problem Definition and the Kinematic Bicycle Model","description":"The parking problem, its state and input variables, and the five-state kinematic bicycle model used by the planner.","permalink":"/notes/optimal-parking/part-1"},{"id":"optimal-parking/part-2","title":"Optimal Parking, Part 2 - RRT* as an Initial Path Planner","description":"Why RRT* is used to generate a collision-free geometric path before trajectory optimization.","permalink":"/notes/optimal-parking/part-2"},{"id":"optimal-parking/part-3","title":"Optimal Parking, Part 3 - Optimal Control and Trajectory Optimization","description":"The optimal-control formulation behind parking trajectories, including cost functions, constraints, MPC, and the role of SQP.","permalink":"/notes/optimal-parking/part-3"},{"id":"optimal-parking/part-4","title":"Optimal Parking, Part 4 - Sequential Quadratic Programming","description":"How the planner refines an initial route through sequential quadratic programs solved with OSQP.","permalink":"/notes/optimal-parking/part-4"},{"id":"optimal-parking/part-5","title":"Optimal Parking, Part 5 - Obstacles, Bounds, and Feasibility","description":"How vehicle bounds, input limits, obstacle constraints, and penalties shape a feasible parking trajectory.","permalink":"/notes/optimal-parking/part-5"},{"id":"optimal-parking/part-6","title":"Optimal Parking, Part 6 - C++ Architecture and the WebAssembly Demo","description":"How the native planner is organized and exposed through WebAssembly for interactive browser experiments.","permalink":"/notes/optimal-parking/part-6"}],"unlisted":false}}')}}]);